for(const mode of ['distribution','local-install','approved-deployment'])test(mode+' complete closure retains original full-stage graph, two owner decisions and a sealed archive across restart',async()=>{const f=await chainFixture(mode);try{const o=await f.advance();assert.equal(o.phase,'COMPLETE',JSON.stringify({reasons:f.view().evidence?.reasons,archive:f.view().evidence?.archive,feedback:f.view().evidence?.feedback}));const v=f.view();assert.equal(v.evidence.archive.status,'COMPLETE');assert.equal(v.evidence.feedback.ontology.status,'REUSE_APPROVED');assert.equal(v.evidence.feedback.harness.status,'REUSE_APPROVED');assert.equal(f.control.ciCalls.filter(x=>x.stageId==='closure').length,1);assert.equal(f.control.feedbackCalls.length,2);const index=JSON.parse(readFileSync(join(v.evidence.archive.directory,'evidence.json')));assert.equal(index.state,'DELIVERY_VERIFIED_CORE_COMMIT_PENDING');for(const kind of ['agent-handoff','agent-claim','agent-report','implementation-review','implementation-evidence','preparation-document','owner-feedback-inbox','owner-decision-attestation','owner-decision-source','publication-evidence','release-material'])assert(index.records.some(r=>r.kind===kind),kind);assert(readdirSync(v.evidence.archive.directory).filter(n=>n.endsWith('.zip')).length>=5);f.restart();assert.equal((await f.read()).phase,'COMPLETE');assert.equal((await f.advance()).phase,'COMPLETE');assert.equal(f.control.ciCalls.filter(x=>x.stageId==='closure').length,1);assert.equal(f.control.feedbackCalls.length,2);f.finish(o);assert.equal(f.instance.stages.closure.status,'PASSED');}finally{f.close();}});

test('passive closure inspection observes undispatched work and never starts CI, Harness, owner delivery or archival',async()=>{const f=await chainFixture();try{const native=f.control.nativeCalls.length;assert.equal((await f.read()).phase,'UNKNOWN');assert.equal(f.view().archiveAction,null);assert.equal(f.view().harness.action,null);assert.equal(f.control.nativeCalls.length,native);assert.equal(f.control.feedbackCalls.length,0);assert.equal(f.control.ciCalls.filter(x=>x.stageId==='closure').length,0);assert.equal((await f.advance()).phase,'COMPLETE');}finally{f.close();}});
