test('tampered sealed archive is FAILED, does not overwrite evidence and cannot report every required check PASS',async()=>{const f=await chainFixture();try{assert.equal((await f.advance()).phase,'COMPLETE');const file=join(f.view().evidence.archive.directory,'evidence.json');writeFileSync(file,'tampered');const o=await f.advance();assert.equal(o.phase,'FAILED');assert(o.outcome.checks.some(c=>c.status==='FAIL'));assert.equal(readFileSync(file,'utf8'),'tampered');assert.equal(f.view().followup.executionAuthorized,false);}finally{f.close();}});
test('changed installed software or another physical target cannot retain delivery acceptance',async()=>{for(const change of ['content','physical']){const f=await chainFixture('local-install');try{if(change==='physical')f.control.physicalMismatch=true;else{assert.equal((await f.advance()).phase,'COMPLETE');writeFileSync(join(f.installed,'index.mjs'),'changed');}assert.equal((await f.advance()).phase,'FAILED');assert.equal(f.view().evidence.smoke.status,'FAILED');assert.equal(f.control.ciCalls.filter(x=>x.stageId==='closure').length,1);}finally{f.close();}}});
test('unknown smoke and incomplete distribution never progress to native evaluation or feedback',async()=>{for(const kind of ['smoke','channel']){const f=await chainFixture();try{const native=f.control.nativeCalls.length;if(kind==='smoke')f.control.smokeStatus='UNKNOWN';else f.control.distribution='PARTIAL';assert.equal((await f.advance()).phase,'UNKNOWN');assert.equal(f.control.nativeCalls.length,native);assert.equal(f.control.feedbackCalls.length,0);assert.equal(f.view().archiveAction,null);}finally{f.close();}}});
test('a rejected current execution permit cannot start closure effects',async()=>{const f=await chainFixture();try{f.control.deny=true;await assert.rejects(()=>f.advance(),{code:'AUTHORITY_REVOKED'});assert.equal(f.control.ciCalls.filter(x=>x.stageId==='closure').length,0);assert.equal(f.control.feedbackCalls.length,0);assert.equal(f.view().ciRequest,null);}finally{f.close();}});
test('full-size original preparation documents retain every byte in bounded archive chunks',async()=>{const f=await chainFixture('distribution',{largePlan:true});try{assert.equal((await f.advance()).phase,'COMPLETE',JSON.stringify(f.view().evidence?.reasons));const a=f.view().evidence.archive,index=JSON.parse(readFileSync(join(a.directory,'evidence.json'))),plans=index.records.filter(r=>r.kind==='preparation-document');assert.equal(plans.length,4);for(const row of plans){const p=JSON.parse(readFileSync(join(a.directory,row.file))),parts=p.parts.map(part=>{const file=index.records.find(x=>x.kind==='original-document-part'&&x.id===part.digest).file,v=JSON.parse(readFileSync(join(a.directory,file)));return Buffer.from(v.base64,'base64');}),bytes=Buffer.concat(parts);assert.equal(bytes.length,p.bytes);assert.equal(byteDigest(bytes),p.digest);assert(bytes.length>1000000);}f.restart();assert.equal((await f.read()).phase,'COMPLETE');}finally{f.close();}});
test('missing original core observation or plan input prevents an incomplete archive from closing',async()=>{for(const kind of ['stage-observation','plan-stage-input']){const f=await chainFixture();try{const progress=f.store.object('alpha','stage-progress','chain-plan'),id=kind==='stage-observation'?progress.observationRef:'chain-plan';f.put([{kind,id,value:null}]);assert.equal((await f.advance()).phase,'UNKNOWN');assert.equal(f.view().archiveAction,null);assert(f.view().evidence.reasons.includes('CLOSURE_PREREQUISITE')||f.view().evidence.reasons.includes('CLOSURE_ARCHIVE_INPUT'));}finally{f.close();}}});

test('actual HTTP and Streamable MCP expose complete large installation evidence without starting effects',async()=>{const f=await chainFixture('local-install',{installationFiles:2500});let server,client;try{assert.equal((await f.advance()).phase,'COMPLETE');const before={ci:f.control.ciCalls.length,native:f.control.nativeCalls.length,feedback:f.control.feedbackCalls.length},connection=await f.service();server=connection.server;const call=async(token,input)=>{const r=await fetch(server.url+'/api/v1/request',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({operation:'lifecycle.closure.evidence.read',projectId:'alpha',input})});return{status:r.status,body:await r.json()};};const read=await call(connection.token,{stageRequestId:f.request.id});assert.equal(read.status,200,JSON.stringify(read));assert.equal(read.body.result.evidence.archive.status,'COMPLETE');assert.equal(read.body.result.evidence.installation.entries.length,2500);assert(Buffer.byteLength(JSON.stringify(read.body))>262144);assert.equal(read.body.result.automaticRedispatch,false);assert.equal((await call(connection.foreign,{stageRequestId:f.request.id})).status,403);assert.equal((await call(connection.token,{stageRequestId:'chain-publication'})).status,409);client=new Client({name:'synthetic-closure-evidence-reader',version:'1.0.0'});await client.connect(new StreamableHTTPClientTransport(new URL(server.url+'/mcp'),{requestInit:{headers:{authorization:'Bearer '+connection.token}}}));const listed=await client.listTools();assert(listed.tools.some(t=>t.name==='runtime_read'));const result=await client.callTool({name:'runtime_read',arguments:{operation:'lifecycle.closure.evidence.read',projectId:'alpha',input:{stageRequestId:f.request.id}}});assert(!result.isError,JSON.stringify(result));assert.deepEqual(JSON.parse(result.content[0].text).result,read.body.result);assert.deepEqual({ci:f.control.ciCalls.length,native:f.control.nativeCalls.length,feedback:f.control.feedbackCalls.length},before);}finally{await client?.close();await server?.close();f.close();}});

test('inline credentials in original preparation bytes are rejected before archive creation rather than hidden in base64 chunks',async()=>{const f=await chainFixture('distribution',{secretPlan:true});try{assert.equal((await f.advance()).phase,'UNKNOWN');assert.equal(f.view().archiveAction,null);assert(f.view().evidence.reasons.includes('CLOSURE_ARCHIVE_INPUT'));}finally{f.close();}});
test('changed retained original document chunk blocks readback without overwriting the sealed archive',async()=>{const f=await chainFixture();try{assert.equal((await f.advance()).phase,'COMPLETE');const a=f.view().evidence.archive,index=JSON.parse(readFileSync(join(a.directory,'evidence.json'))),part=index.records.find(x=>x.kind==='original-document-part'),original=f.store.object('alpha','closure-archive-document-part',part.id);f.put([{kind:'closure-archive-document-part',id:part.id,value:{...original,base64:Buffer.from('tampered').toString('base64')}}]);assert.equal((await f.read()).phase,'UNKNOWN');assert(f.view().evidence.reasons.includes('CLOSURE_ARCHIVE_INPUT'));const archived=JSON.parse(readFileSync(join(a.directory,part.file)));assert.equal(archived.base64,original.base64);assert.equal(f.control.ciCalls.filter(x=>x.stageId==='closure').length,1);}finally{f.close();}});

test('closure archives the exact native extension action, complete receipt and passing stage evidence',async()=>{
 const f=await chainFixture('distribution',{nativeExtension:true});try{const id=f.instance.stages['project.closure-native'].requestId;assert.equal((await f.advance()).phase,'COMPLETE',JSON.stringify(f.view().evidence?.reasons));const directory=f.view().evidence.archive.directory,index=JSON.parse(readFileSync(join(directory,'evidence.json')));for(const kind of ['extension-native-action','extension-native-receipt','extension-evidence']){const row=index.records.find(r=>r.kind===kind);assert(row,kind);const actual=JSON.parse(readFileSync(join(directory,row.file)));assert.deepEqual(actual,f.store.object('alpha',kind,kind==='extension-evidence'?row.id:id));}f.restart();assert.equal((await f.read()).phase,'COMPLETE');}finally{f.close();}
});
for(const kind of ['extension-native-action','extension-native-receipt','extension-evidence'])test('missing original '+kind+' prevents closure archival despite a passed extension stage',async()=>{
 const f=await chainFixture('distribution',{nativeExtension:true});try{const id=f.instance.stages['project.closure-native'].requestId,pointer=f.store.object('alpha','extension-evidence-pointer',id);f.put([{kind,id:kind==='extension-evidence'?pointer.ref:id,value:null}]);const result=await f.advance();assert.notEqual(result.phase,'COMPLETE');assert.equal(f.view().archiveAction,null);assert(f.view().evidence.reasons.includes('CORRUPT_EXTENSION'));}finally{f.close();}
});

for(const slot of ['after-plan','before-candidate','candidate-checks','before-release-decision'])test(slot+' artifact extension verifies exact original bytes and native Harness before full closure',async()=>{
 const f=await chainFixture('distribution',{nativeExtension:true,extensionAction:'artifact',extensionSlot:slot});try{
  const calls=f.control.nativeCalls.filter(c=>c.request.requestId.startsWith('extension-native-'));assert.equal(calls.length,1);assert.equal(calls[0].kind,'harness');const observed=calls[0].request.input.observation.values.runtimeExtension.artifacts;
  assert.equal(observed.schema,'runtime-extension-artifacts/v1');assert.equal(observed.kind,slot==='after-plan'?'reviewed-documents':slot==='before-candidate'?'implementation-ci':'candidate-ci');
  if(slot==='after-plan'){assert.equal(Object.keys(observed.documents).length,4);for(const x of Object.values(observed.documents)){const b=readFileSync(x.path);assert.equal(byteDigest(b),x.digest);assert.equal(b.length,x.bytes);}}
  else{const a=observed.artifact;assert.equal(a.status,'PASSED');assert.equal(a.sourceArchive.archiveDigest,byteDigest(readFileSync(join(f.dir,'state','stage-ci-artifacts',a.archiveDigest.slice(7)+'.zip'))));assert(a.files.some(x=>x.path==='runtime-result.json'));assert.equal(a.candidateDigest,slot==='before-candidate'?null:f.instance.candidateDigest);}
  assert.equal((await f.advance()).phase,'COMPLETE',JSON.stringify(f.view().evidence?.reasons));assert.equal(f.control.ciCalls.length,5,'artifact inspection cannot dispatch additional CI');f.restart();assert.equal((await f.read()).phase,'COMPLETE');
 }finally{f.close();}
});
for(const slot of ['after-plan','before-candidate','candidate-checks','before-release-decision'])test(slot+' artifact drift after exact planning blocks all native effects',async()=>{
 const f=await chainFixture('distribution',{nativeExtension:true,extensionAction:'artifact',extensionSlot:slot,stopAtExtension:true});try{
  const plan=await f.prepare(),r=f.request(plan),before=f.control.nativeCalls.length,input=plan.parameters.artifactInput;
  const path=input.kind==='reviewed-documents'?input.documents.plan.path:join(f.root,'stage-ci-artifacts',input.artifact.archiveDigest.slice(7)+'.zip');writeFileSync(path,'Tampered original artifact');
  await assert.rejects(()=>f.dispatch(r),{code:slot==='after-plan'?'RESOURCE_CHANGED':'EXTENSION_ARTIFACT'});assert.equal(f.control.nativeCalls.length,before);assert.equal(f.store.object('alpha','extension-native-action',r.id),null);
 }finally{f.close();}
});
for(const modification of ['missing-archive','wrong-candidate','missing-result','changed-result'])test('candidate artifact extension rejects '+modification+' without rebuilding or native validation',async()=>{
 const f=await chainFixture('distribution',{nativeExtension:true,extensionAction:'artifact',extensionSlot:'candidate-checks',stopAtExtension:true});try{
  const plan=await f.prepare(),r=f.request(plan),before=f.control.nativeCalls.length,p=plan.parameters,input=p.artifactInput,original=f.store.object('alpha','stage-request',f.instance.stages.candidate.requestId);
  if(modification==='missing-archive')unlinkSync(join(f.root,'stage-ci-artifacts',input.artifact.archiveDigest.slice(7)+'.zip'));
  else if(modification==='wrong-candidate')p.candidateInput.archive.artifactId='1234567';
  else{const v=modification==='missing-result'?null:{...input.artifact,files:[]};f.store.mutate({id:'test',projects:['alpha'],permissions:['read'],revision:1,expiresAt:'2030-01-01T00:00:00Z'},{projectId:'alpha',operation:'synthetic-tamper',requestId:'tamper-artifact',expectedRevision:f.store.revision('alpha'),input:{synthetic:true},permission:'read'},()=>({objects:[{kind:'ci-stage-artifact',id:original.id,value:v}],value:{synthetic:true},event:{type:'synthetic-tamper',data:{}}}));}
  await assert.rejects(()=>f.dispatch(r));assert.equal(f.control.nativeCalls.length,before);assert.equal(f.store.object('alpha','extension-native-action',r.id),null);
 }finally{f.close();}
});

for(const slot of ['after-plan','before-candidate','candidate-checks','before-release-decision'])test(slot+' scope decision survives the full candidate lifecycle and is archived with original evidence',async()=>{
 const f=await chainFixture('distribution',{nativeExtension:true,extensionAction:'review',extensionSlot:slot});try{
  const request=f.store.object('alpha','stage-request',f.instance.stages['project.closure-native'].requestId),view=readExtensionReviewEvidence(f.store,request);assert.equal(view.decision.choice,'APPROVE');assert.equal((await f.advance()).phase,'COMPLETE',JSON.stringify(f.view().evidence?.reasons));const directory=f.view().evidence.archive.directory,index=JSON.parse(readFileSync(join(directory,'evidence.json')));
  for(const kind of ['extension-review','extension-review-evidence','extension-review-decision-attestation','extension-review-decision-source'])assert(index.records.some(r=>r.kind===kind),kind);const row=index.records.find(r=>r.kind==='extension-review');assert.deepEqual(JSON.parse(readFileSync(join(directory,row.file))),view.decision);f.restart();assert.equal((await f.read()).phase,'COMPLETE');
 }finally{f.close();}
});
test('missing or revoked original scope decision prevents closure even if historical stage passed',async()=>{
 for(const variation of ['missing','revoked']){const f=await chainFixture('distribution',{nativeExtension:true,extensionAction:'review'});try{const id=f.instance.stages['project.closure-native'].requestId,r=f.store.object('alpha','stage-request',id),v=readExtensionReviewEvidence(f.store,r);f.put([{kind:variation==='missing'?'extension-review':'extension-review-revocation',id:v.decision.ref,value:variation==='missing'?null:{reviewRef:v.decision.ref,reason:'Synthetic revocation'}}]);const result=await f.advance();assert.notEqual(result.phase,'COMPLETE');assert.equal(f.view().archiveAction,null);}finally{f.close();}}
});

for(const action of [null,'artifact','review'])test('source-changing CI preparation '+(action?'with downstream '+action:'alone')+' remains exact through full closure and restart',async()=>{
 const f=await chainFixture('distribution',{ciPreparation:true,nativeExtension:!!action,extensionAction:action??'harness',extensionSlot:'before-candidate'});try{
  assert.equal(f.instance.candidate.sourceDigest,ciSourceDigest({commit:'c'.repeat(40)},'github','42'));assert.equal(f.control.ciCalls.filter(c=>c.stageId==='project.prepare').length,1);
  if(action==='artifact'){const native=f.control.nativeCalls.find(c=>c.request.requestId.startsWith('extension-native-')).request.input.observation.values.runtimeExtension;assert.equal(native.source.commit,'c'.repeat(40));assert.equal(native.artifacts.kind,'prepared-ci');assert.equal(native.artifacts.preparations.length,1);assert.equal(native.artifacts.preparations[0].source.commit,'c'.repeat(40));}
  if(action==='review'){const r=f.store.object('alpha','stage-request',f.instance.stages['project.closure-native'].requestId),v=readExtensionReviewEvidence(f.store,r);assert.equal(r.plan.parameters.facts.source.commit,'c'.repeat(40));assert.equal(v.decision.choice,'APPROVE');}
  const result=await f.advance();assert.equal(result.phase,'COMPLETE',JSON.stringify(f.view().evidence?.reasons));const index=JSON.parse(readFileSync(join(f.view().evidence.archive.directory,'evidence.json'))),id=f.instance.stages['project.prepare'].requestId;
  for(const kind of ['ci-preparation-observation','ci-preparation-source','ci-stage-run','ci-stage-observation','ci-stage-artifact']){const row=index.records.find(r=>r.kind===kind&&r.id===id);assert(row,kind);assert.deepEqual(JSON.parse(readFileSync(join(f.view().evidence.archive.directory,row.file))),f.store.object('alpha',kind,id));}
  assert.equal(completedPreparationSource(f.store,f.instance,'project.prepare').output.commit,'c'.repeat(40));f.restart();assert.equal((await f.read()).phase,'COMPLETE');assert.equal((await f.advance()).phase,'COMPLETE');assert.equal(f.control.ciCalls.filter(c=>c.stageId==='project.prepare').length,1);
 }finally{f.close();}
});
for(const kind of ['ci-preparation-observation','ci-preparation-source','ci-stage-artifact','ci-stage-run'])test('closure cannot hide a missing original preparation '+kind,async()=>{
 const f=await chainFixture('distribution',{ciPreparation:true});try{const id=f.instance.stages['project.prepare'].requestId;f.put([{kind,id,value:null}]);const result=await f.advance();assert.notEqual(result.phase,'COMPLETE');assert.equal(f.view().archiveAction,null);}finally{f.close();}
});
test('artifact extension after preparation rejects a missing original prepared archive without rebuilding',async()=>{
 const f=await chainFixture('distribution',{ciPreparation:true,nativeExtension:true,extensionAction:'artifact',extensionSlot:'before-candidate',stopAtExtension:true});try{const id=f.instance.stages['project.prepare'].requestId,artifact=f.store.object('alpha','ci-stage-artifact',id),before=f.control.nativeCalls.length;rmSync(join(f.root,'stage-ci-artifacts',artifact.archiveDigest.slice(7)+'.zip'));await assert.rejects(()=>f.prepare());assert.equal(f.control.nativeCalls.length,before);assert.equal(f.control.ciCalls.filter(c=>c.stageId==='project.prepare').length,1);}finally{f.close();}
});
